def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return:
    """
    if value is None:
        return None
    try:
        # Convert timedelta to total seconds as a float
        total_seconds = value.total_seconds()
        return total_seconds
    except (AttributeError, TypeError):
        # If value is not a timedelta, try to convert it
        try:
            from datetime import timedelta
            if isinstance(value, timedelta):
                return value.total_seconds()
            else:
                # Try to parse as a string or other format
                # For simplicity, if it's a number, assume it's seconds
                if isinstance(value, (int, float)):
                    return float(value)
                else:
                    raise ValueError(f"Cannot dehydrate value of type {type(value)}")
        except Exception:
            raise ValueError(f"Cannot dehydrate value of type {type(value)}")

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None
    try:
        # If it's a datetime.time object, convert to string
        if hasattr(value, 'strftime'):
            return value.strftime('%H:%M:%S')
        # If it's already a string, return as is
        elif isinstance(value, str):
            return value
        else:
            return str(value)
    except Exception:
        return str(value)

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if value is None:
        return None
    try:
        # Assuming Point has x and y attributes
        return {"x": value.x, "y": value.y}
    except AttributeError:
        # If it's already a dict or doesn't have x, y attributes
        if isinstance(value, dict):
            return value
        # Try to convert to a dict if it's a tuple or list
        if isinstance(value, (tuple, list)) and len(value) >= 2:
            return {"x": value[0], "y": value[1]}
        # Fallback: return the value as is or raise an error
        return value

