def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    if not keys:
        return list(self._values)

    result = []
    for key in keys:
        if isinstance(key, int):
            if 0 <= key < len(self._values):
                result.append(self._values[key])
            else:
                raise IndexError("Index out of range")
        elif isinstance(key, str):
            if key in self._keys:
                idx = self._keys.index(key)
                result.append(self._values[idx])
            else:
                raise KeyError(key)
        else:
            raise TypeError("Key must be an integer or string")
    return result

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    import warnings
    import functools

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    # Remove leading 'v' or 'V' if present
    s = s.strip()
    if s.startswith(('v', 'V')):
        s = s[1:]
    # Split by dots
    parts = s.split('.')
    result = []
    for part in parts:
        # Remove any non-digit suffixes (like 'a', 'b', 'rc', etc.)
        # Find the first non-digit character
        i = 0
        while i < len(part) and part[i].isdigit():
            i += 1
        numeric_part = part[:i]
        if numeric_part == '':
            # If no digits found, treat as 0
            result.append(0)
        else:
            result.append(int(numeric_part))
    return tuple(result)

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            k = key(*args, **kwargs)
            if lock is not None:
                with lock:
                    if k in cache:
                        return cache[k]
                    result = func(*args, **kwargs)
                    cache[k] = result
                    return result
            else:
                if k in cache:
                    return cache[k]
                result = func(*args, **kwargs)
                cache[k] = result
                return result
        return wrapper
    return decorator

def setdefault(self, key, default=None):
    """
    D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D
    """
    if key in self:
        return self[key]
    else:
        self[key] = default
        return default

def get(self, key, default=None):
