def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return []

    # Remove duplicates while preserving order
    seen = set()
    unique_classes = []
    for cls in classes:
        if cls not in seen:
            seen.add(cls)
            unique_classes.append(cls)

    # Now remove any class that is a subclass of another class in the list
    # We want to keep only the most general (base) classes
    # A class is redundant if it is a subclass of another class in the list
    minimal = []
    for i, cls in enumerate(unique_classes):
        # Check if cls is a subclass of any other class in unique_classes
        is_redundant = False
        for j, other in enumerate(unique_classes):
            if i == j:
                continue
            # If cls is a subclass of other, then cls is redundant
            if issubclass(cls, other):
                is_redundant = True
                break
        if not is_redundant:
            minimal.append(cls)

    return minimal

def namesAndDescriptions(self, all=False): # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    # Get the interface's attributes
    try:
        if all:
            # Get all attributes including inherited ones
            attrs = self.__dict__.copy()
            # Also include class attributes
            for klass in type(self).__mro__:
                for key, value in vars(klass).items():
                    if not key.startswith('_'):
                        attrs[key] = value
        else:
            # Get only the attributes defined directly on this instance
            attrs = self.__dict__.copy()
    except Exception as e:
        raise RuntimeError(f"Error accessing attributes: {e}")

    # Filter out private attributes and non-describable items
    result = {}
    for name, value in attrs.items():
        if name.startswith('_'):
            continue
        # Try to get the description from the docstring or a 'description' attribute
        description = None
        if hasattr(value, '__doc__') and value.__doc__:
            description = value.__doc__.strip()
        elif hasattr(value, 'description'):
            description = value.description
        elif isinstance(value, str):
            description = value
        else:
            # Try to get a description from the class
            if hasattr(value, '__class__'):
                cls = value.__class__
                if hasattr(cls, '__doc__') and cls.__doc__:
                    description = cls.__doc__.strip()

        if description is None:
            description = ""

        result[name] = description

    return result

