def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    if not hasattr(self, 'status'):
        return prefix + "Unknown"
    status = self.status
    if status is None:
        return prefix + "Unknown"
    if isinstance(status, str):
        return prefix + status
    if isinstance(status, bool):
        return prefix + ("Valid" if status else "Invalid")
    if isinstance(status, int):
        # Assuming 0 is invalid, non-zero is valid, or specific codes
        if status == 0:
            return prefix + "Invalid"
        else:
            return prefix + "Valid"
    # Fallback
    return prefix + str(status)

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    if not hasattr(self, 'log') or self.log is None:
        return prefix
    if isinstance(self.log, str):
        return prefix + self.log
    if isinstance(self.log, list):
        return prefix + '\n'.join(str(item) for item in self.log)
    if isinstance(self.log, dict):
        lines = []
        for key, value in self.log.items():
            lines.append(f"{key}: {value}")
        return prefix + '\n'.join(lines)
    return prefix + str(self.log)

def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used."""
        # Collect all digests from manifest files
        manifest_digests = set()
        for file_path in manifest_files:
            try:
                with open(file_path, 'r') as f:
                    for line in f:
                        line = line.strip()
                        if line:
                            manifest_digests.add(line)
            except (IOError, OSError) as e:
                raise IOError(f"Failed to read manifest file {file_path}: {e}")

        # Check for digests in manifest that are not used
        unused_digests = manifest_digests - set(digests_used)
        if unused_digests:
            raise ValueError(f"Digests present in manifest but not used: {unused_digests}")

        # Check for digests used that are not in manifest
        missing_digests = set(digests_used) - manifest_digests
        if missing_digests:
            raise ValueError(f"Digests used but not present in manifest: {missing_digests}")

        return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # We need to find all files in the inventory that are associated with the given version
    # and map their logical paths to the set of content files.

    # The inventory is expected to be a dictionary or object that contains version information.
    # Based on the docstring, we need to return a dictionary mapping logical_path_in_state to a set of content_files.

    # Let's assume the inventory has a structure that allows us to iterate over files or entries.
    # A common pattern might be that inventory is a dict with keys like 'files' or it's a list of file objects.
    # Since the exact structure isn't specified, we'll make reasonable assumptions.

    # Let's assume inventory is a dictionary where each key is a version and the value is a list of file objects.
    # Each file object might have attributes like 'logical_path' and 'content_file' or similar.

    # Alternatively, inventory might be a list of file objects, each with a 'version' attribute.

    # Given the ambiguity, let's try a more generic approach:
    # We'll look for a way to get files for the given version from the inventory.

    # Let's assume inventory is a dict mapping version to a list of file descriptors.
    # Each file descriptor is a dict with keys 'logical_path' and 'content_file'.

    # But to be safe, let's handle multiple possible structures.

    # First, check if inventory is a dict and has the version as a key
    if isinstance(inventory, dict):
        if version in inventory:
            files = inventory[version]
        else:
            # Maybe the version is stored differently, or we need to look through all versions
            # Let's try to find files that match the version
            files = []
            for ver, file_list in inventory.items():
                if ver == version:
                    files.extend(file_list)
                    break
            # If not found, maybe we should look at all files and filter by version attribute
            if not files:
                for ver, file_list in inventory.items():
                    for f in file_list:
                        if isinstance(f, dict) and f.get('version') == version:
                            files.append(f)
                        elif hasattr(f, 'version') and f.version == version:
                            files.append(f)
    elif isinstance(inventory, list):
        # inventory is a list of file objects
        files = []
        for f in inventory:
            if isinstance(f, dict) and f.get('version') == version:
                files.append(f)
            elif hasattr(f, 'version') and f.version == version:
                files.append(f)
    else:
        # Unknown structure, return empty dict
        return {}

    # Now, build the map
    logical_path_map = {}

    for f in files:
        if isinstance(f, dict):
            logical_path = f.get('logical_path')
            content_file = f.get('content_file')
        elif hasattr(f, 'logical_path') and hasattr(f, 'content_file'):
            logical_path = f.logical_path
            content_file = f.content_file
        else:
            continue

        if logical_path is None or content_file is None:
            continue

        if logical_path not in logical_path_map:
            logical_path_map[logical_path] = set()
        logical_path_map[logical_path].add(content_file)

    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        if not isinstance(fixity, dict):
            raise ValueError("Fixity must be a dictionary")

        if not isinstance(manifest_files, (list, set, tuple)):
            raise ValueError("Manifest files must be a list, set, or tuple")

        manifest_set = set(manifest_files)

        for file_path, checksum in fixity.items():
            if not isinstance(file_path, str):
                raise ValueError(f"File path must be a string, got {type(file_path)}")
            if not isinstance(checksum, str):
                raise ValueError(f"Checksum must be a string, got {type(checksum)}")
            if file_path not in manifest_set:
                raise ValueError(f"File {file_path} is not in the manifest")

        return True

def files_list(path):
    """
    Return the files in `path`
    """
    import os
    try:
        if not os.path.exists(path):
            raise FileNotFoundError(f"Path does not exist: {path}")
        if not os.path.isdir(path):
            raise NotADirectoryError(f"Path is not a directory: {path}")
        files = []
        for entry in os.listdir(path):
            full_path = os.path.join(path, entry)
            if os.path.isfile(full_path):
                files.append(entry)
        return files
    except Exception as e:
        raise e

