def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if style == "pep440":
        # PEP 440 style
        if pieces["distance"] == 0:
            if pieces["closest-tag"]:
                rendered = pieces["closest-tag"]
            else:
                rendered = pieces["version"]
        else:
            if pieces["closest-tag"]:
                rendered = pieces["closest-tag"] + ".dev" + str(pieces["distance"])
            else:
                rendered = pieces["version"] + ".dev" + str(pieces["distance"])
        if pieces["dirty"]:
            rendered += ".dirty"
        return rendered
