    elif style == "git-describe":
        # git describe style
        if pieces["distance"] == 0:
            if pieces["closest-tag"]:
                rendered = pieces["closest-tag"]
            else:
                rendered = pieces["version"]
        else:
            if pieces["closest-tag"]:
                rendered = pieces["closest-tag"] + "-" + str(pieces["distance"]) + "-" + pieces["short"]
            else:
                rendered = pieces["version"] + "-" + str(pieces["distance"]) + "-" + pieces["short"]
        if pieces["dirty"]:
            rendered += "-dirty"
        return rendered
    elif style == "git-describe-long":
        # git describe long style
        if pieces["distance"] == 0:
            if pieces["closest-tag"]:
                rendered = pieces["closest-tag"]
            else:
                rendered = pieces["version"]
        else:
            if pieces["closest-tag"]:
                rendered = pieces["closest-tag"] + "-" + str(pieces["distance"]) + "-" + pieces["short"]
            else:
                rendered = pieces["version"] + "-" + str(pieces["distance"]) + "-" + pieces["short"]
        if pieces["dirty"]:
            rendered += "-dirty"
        return rendered
    elif style == "python":
        # Python style
        if pieces["distance"] == 0:
            if pieces["closest-tag"]:
                rendered = pieces["closest-tag"]
            else:
                rendered = pieces["version"]
        else:
            if pieces["closest-tag"]:
                rendered = pieces["closest-tag"] + ".dev" + str(pieces["distance"])
            else:
                rendered = pieces["version"] + ".dev" + str(pieces["distance"])
        if pieces["dirty"]:
