    # If commands is a string, split it into a list
    if isinstance(commands, str):
        commands = commands.split()

    # If args is a string, split it into a list
    if isinstance(args, str):
        args = args.split()

    # Combine commands and args
    full_command = commands + args

    # Set up environment
    if env is None:
        env = os.environ.copy()
    else:
        env = os.environ.copy()
        env.update(env)

    # Set up stderr handling
    stderr = subprocess.DEVNULL if hide_stderr else None

    # Run the command
    try:
        if verbose:
            print(f"Running command: {' '.join(full_command)}")

        result = subprocess.run(
            full_command,
            cwd=cwd,
            env=env,
            stderr=stderr,
            stdout=subprocess.PIPE,
            text=True
        )

        if verbose:
            if result.stdout:
                print(result.stdout)
            if result.stderr and not hide_stderr:
                print(result.stderr, file=sys.stderr)

        return result
    except Exception as e:
        if verbose:
            print(f"Error running command: {e}", file=sys.stderr)
        raise

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """Validate storage root hierarchy.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid
        """
        num_objects = 0
        good_objects = 0

        # Check if the storage root exists and is valid
        if not hasattr(self, 'root') or self.root is None:
            if show_warnings:
                print("Warning: No storage root defined.")
            return num_objects, good_objects

        # Validate the root object
        try:
            if validate_objects:
                # Check if the root object is valid
                if hasattr(self.root, 'is_valid') and callable(self.root.is_valid):
                    if self.root.is_valid():
                        good_objects += 1
                    else:
                        if show_warnings:
                            print("Warning: Root object is invalid.")
                else:
                    # Assume it's valid if no is_valid method
                    good_objects += 1
            num_objects += 1
        except Exception as e:
            if show_warnings:
                print(f"Warning: Error validating root object: {e}")

        # Check digests if required
        if check_digests:
            try:
                if hasattr(self.root, 'digest') and self.root.digest is not None:
                    # Check if digest is valid (e.g., not empty)
                    if not self.root.digest:
                        if show_warnings:
                            print("Warning: Root object has empty digest.")
                else:
                    if show_warnings:
                        print("Warning: Root object has no digest.")
            except Exception as e:
                if show_warnings:
                    print(f"Warning: Error checking root digest: {e}")

        # Validate child objects if they exist
        if hasattr(self.root, 'children') and self.root.children:
            for child in self.root.children:
                try:
                    if validate_objects:
                        if hasattr(child, 'is_valid') and callable(child.is_valid):
                            if child.is_valid():
                                good_objects += 1
                            else:
                                if show_warnings:
                                    print("Warning: Child object is invalid.")
                        else:
                            # Assume it's valid if no is_valid method
                            good_objects += 1
                    num_objects += 1
                except Exception as e:
                    if show_warnings:
                        print(f"Warning: Error validating child object: {e}")

                if check_digests:
                    try:
                        if hasattr(child, 'digest') and child.digest is not None:
                            # Check if digest is valid (e.g., not empty)
                            if not child.digest:
                                if show_warnings:
                                    print("Warning: Child object has empty digest.")
                        else:
                            if show_warnings:
                                print("Warning: Child object has no digest.")
                    except Exception as e:
                        if show_warnings:
                            print(f"Warning: Error checking child digest: {e}")

        return num_objects, good_objects

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")

    # Split by dots
    parts = version.split('.')

    # Check if all parts are numeric (allowing leading zeros)
    for part in parts:
        if not part.isdigit():
            raise ValueError(f"Invalid version component: {part}")

    # Determine if the version uses zero-prefixed format
    # A version is zero-prefixed if any part has leading zeros (and length > 1)
    zero_prefixed = any(len(part) > 1 and part[0] == '0' for part in parts)

    # Convert to integers
    nums = [int(part) for part in parts]

    # Increment the last component
    nums[-1] += 1

    # Format back to string
    if zero_prefixed:
        # Preserve the original width of each part
        result_parts = []
        for i, (orig_part, num) in enumerate(zip(parts, nums)):
            width = len(orig_part)
            result_parts.append(str(num).zfill(width))
        return '.'.join(result_parts)
    else:
        return '.'.join(str(num) for num in nums)

def validate_version_inventories(self, version_dirs):
        """Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        if not isinstance(version_dirs, (list, tuple)):
            raise TypeError("version_dirs must be a list or tuple")

        # Assume self has attributes:
        # self.root_inventory: dict mapping path -> digest
        # self.version_inventories: dict mapping version -> dict mapping path -> digest
        # self.content_digests: dict mapping path -> set of digests (or similar)

        # We'll build a record of content digests that differ from root inventory
        # and validate that each version has an inventory.

        # Initialize if not present
        if not hasattr(self, 'version_inventories'):
            self.version_inventories = {}
        if not hasattr(self, 'content_digests'):
            self.content_digests = {}

        for version in version_dirs:
            # Check if inventory exists for this version
            if version not in self.version_inventories:
                # This is a SHOULD, so we might just warn or skip
                # But for validation, we might want to raise or record
                # Let's assume we need to have it, so raise an error
                raise ValueError(f"Missing inventory for version {version}")

            version_inv = self.version_inventories[version]

            # Compare with root inventory
            if not hasattr(self, 'root_inventory'):
                self.root_inventory = {}

            for path, digest in version_inv.items():
                if path in self.root_inventory:
                    root_digest = self.root_inventory[path]
                    if digest != root_digest:
                        # Record this difference
                        if path not in self.content_digests:
                            self.content_digests[path] = set()
                        self.content_digests[path].add(digest)
                else:
                    # Path not in root inventory, record its digest
                    if path not in self.content_digests:
                        self.content_digests[path] = set()
                    self.content_digests[path].add(digest)

        return True

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")
    if not isinstance(bug_ids, (list, tuple)):
        raise TypeError("bug_ids must be a list or tuple")

    # Ensure bug_ids are integers
    for bug_id in bug_ids:
        if not isinstance(bug_id, int):
            raise TypeError("All bug_ids must be integers")

    # Create a copy of params to avoid modifying the original
    amended_params = params.copy()

    # Add or update the bug_ids in the params
    amended_params['bug_ids'] = list(bug_ids)

    return amended_params

def parser_flags(parser):
    '''
