def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet must not be empty")

    base = len(alphabet)

    if number == 0:
        result = alphabet[0]
    else:
        digits = []
        n = number
        while n > 0:
            n, remainder = divmod(n, base)
            digits.append(alphabet[remainder])
        result = ''.join(reversed(digits))

    if padding is not None:
        if len(result) < padding:
            result = alphabet[0] * (padding - len(result)) + result

    return result

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    if not isinstance(flow_params, dict):
        raise TypeError("flow_params must be a dictionary")

    # Iterate over a copy of the items to avoid modification during iteration
    for key, value in list(flow_params.items()):
        if isinstance(value, dict):
            if register_value in value:
                # Replace the value with the register number
                value[register_value] = register_number
        elif isinstance(value, list):
            # If value is a list, check if any element is a dict containing the key
            for item in value:
                if isinstance(item, dict) and register_value in item:
                    item[register_value] = register_number
        # If value is neither dict nor list, do nothing
    return flow_params

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        raise TypeError("value must be a string")
    if not isinstance(arg, str):
        raise TypeError("arg must be a string")
    return value.replace('.', arg)

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError("Expected a class, got {}".format(type(cls)))

    result = set()
    def _collect(c):
        for sub in c.__subclasses__():
            if sub not in result:
                result.add(sub)
                _collect(sub)
    _collect(cls)
    return result

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not string:
        return 0

    # Build a mapping from character to its index in the alphabet
    char_to_index = {}
    for i, char in enumerate(alphabet):
        char_to_index[char] = i

    base = len(alphabet)
    result = 0

    for char in string:
        if char not in char_to_index:
            raise ValueError(f"Character '{char}' not found in alphabet")
        result = result * base + char_to_index[char]

    return result

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    if len(name) >= 2 and name[0] == name[-1] and name[0] in ('"', "'"):
        return name[1:-1]
    return name

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import sys

    import shlex
    if platform == 'this':
        if sys.platform == 'win32':
            platform = 0
        else:
            platform = 1

    if platform == 1:
        # POSIX: use shlex.split
        try:
            return shlex.split(s)
        except ValueError:
            # If shlex fails, fall back to a simple split
            return s.split()
    elif platform == 0:
        # Windows/CMD: handle quotes and escapes
        # Windows command line parsing rules:
        # - Double quotes are used to group arguments
        # - Backslash is used to escape quotes
        # - Single quotes are not special
        # - Spaces and tabs separate arguments
        # - Empty arguments are not preserved (unlike POSIX)

        result = []
        current = []
        in_quotes = False
        i = 0
        n = len(s)

        while i < n:
            c = s[i]

            if c == '\\':
                # Check if next char is a quote
                if i + 1 < n and s[i+1] == '"':
                    # Escaped quote
                    current.append('"')
                    i += 2
                    continue
                else:
                    # Backslash is literal
                    current.append(c)
                    i += 1
                    continue
            elif c == '"':
                in_quotes = not in_quotes
                i += 1
                continue
            elif c in (' ', '\t') and not in_quotes:
                # End of current argument
                if current:
                    result.append(''.join(current))
                    current = []
                i += 1
                continue
            else:
                current.append(c)
                i += 1
                continue

        # Add last argument if any
        if current:
            result.append(''.join(current))

        return result
    else:
        raise ValueError(f"Invalid platform value: {platform}")

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    import socket
    if host is None:
        return False

    # Check for common localhost representations
    if host in ('localhost', '127.0.0.1', '::1'):
        return True

    # Try to resolve the hostname
    try:
        # Get all address info
        addr_info = socket.getaddrinfo(host, None)
        for family, socktype, proto, canonname, sockaddr in addr_info:
            ip = sockaddr[0]
            if ip in ('127.0.0.1', '::1'):
                return True
            # Check if it's a loopback address
            if family == socket.AF_INET:
                import ipaddress
                try:
                    if ipaddress.ip_address(ip).is_loopback:
                        return True
                except ValueError:
                    pass
            elif family == socket.AF_INET6:
                import ipaddress
                try:
                    if ipaddress.ip_address(ip).is_loopback:
                        return True
                except ValueError:
                    pass
    except socket.gaierror:
        # Could not resolve the host
        return False
    except Exception:
        return False

    return False

def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    # The matcher is expected to be a string in the format "name" or "name:default"
    # We need to parse it to extract the name and optional default value.

    if not isinstance(matcher, str):
        raise TypeError("matcher must be a string")

    # Split by the first colon to separate name and default
    if ':' in matcher:
        name, default = matcher.split(':', 1)
    else:
        name = matcher
        default = None

    # Get the value from environment
    value = os.environ.get(name)

    if value is not None:
        return value
    elif default is not None:
        return default
    else:
        raise EnvironmentError(f"Environment variable '{name}' is not set and no default value provided")

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:

    """
    if not image_href:
        raise ValueError("image_href must be a non-empty string")

    # Check if it's a valid URL
    try:
        parsed = urllib.parse.urlparse(image_href)
    except Exception as e:
        raise ValueError(f"Invalid image href: {e}")

    # Extract netloc
    netloc = parsed.netloc

    # Determine use_ssl
    use_ssl = parsed.scheme == 'https'

    # Extract image_id from path
    path = parsed.path
    if not path:
        raise ValueError("No path found in image href")

    # Remove leading slash
    if path.startswith('/'):
        path = path[1:]

    # The image_id is the last part of the path
    if '/' in path:
        image_id = path.split('/')[-1]
    else:
        image_id = path

    if not image_id:
        raise ValueError("No image id found in image href")

    return (image_id, netloc, use_ssl)

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    if isinstance(commands, str):
        commands = [commands]
    if not isinstance(commands, (list, tuple)):
        raise TypeError("commands must be a string or a list/tuple of strings")
    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a list or tuple")

    full_command = commands + list(args)

    if verbose:
        print("Running command: " + " ".join(full_command))

    try:
        if hide_stderr:
            result = subprocess.run(full_command, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)
        else:
            result = subprocess.run(full_command, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE)

        if verbose:
            if result.stdout:
                print("stdout: " + result.stdout.decode('utf-8', errors='replace'))
            if result.stderr and not hide_stderr:
                print("stderr: " + result.stderr.decode('utf-8', errors='replace'))

        return result
    except Exception as e:
        if verbose:
            print("Error running command: " + str(e))
        raise

