def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    try:
        # Validate shape
        if not isinstance(shape, (tuple, list)):
            raise TypeError("shape must be a tuple or list")
        if len(shape) == 0:
            raise ValueError("shape must not be empty")
        for dim in shape:
            if not isinstance(dim, (int, np.integer)):
                raise TypeError("each dimension in shape must be an integer")
            if dim < 0:
                raise ValueError("each dimension in shape must be non-negative")

        # Validate dtype
        if not isinstance(dtype, np.dtype):
            try:
                dtype = np.dtype(dtype)
            except TypeError:
                raise TypeError("dtype must be a valid numpy dtype")

        # Create the array
        return np.zeros(shape, dtype=dtype)
    except Exception as e:
        raise e

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    import logging

    import os

    import json

    import yaml

    import re

    def _deep_merge(base, override):
        """Recursively merge override into base, with override taking precedence."""
        if not isinstance(base, dict) or not isinstance(override, dict):
            return override

        result = base.copy()
        for key, value in override.items():
            if key in result and isinstance(result[key], dict) and isinstance(value, dict):
                result[key] = _deep_merge(result[key], value)
            else:
                result[key] = value
        return result

    def _resolve_env_vars(obj):
        """Recursively resolve environment variables in string values."""
        if isinstance(obj, dict):
            return {k: _resolve_env_vars(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [_resolve_env_vars(item) for item in obj]
        elif isinstance(obj, str):
            # Replace ${VAR} or $VAR patterns with environment variable values
            def replace_env(match):
                var_name = match.group(1) or match.group(2)
                return os.environ.get(var_name, match.group(0))

            # Match ${VAR} or $VAR
            pattern = r'\$\{([A-Za-z_][A-Za-z0-9_]*)\}|\$([A-Za-z_][A-Za-z0-9_]*)'
            return re.sub(pattern, replace_env, obj)
        else:
            return obj
    if not config_filenames:
        return {}, []

    if not isinstance(config_filenames, (list, tuple)):
        config_filenames = [config_filenames]

    if overrides is None:
        overrides = {}
    elif not isinstance(overrides, dict):
        overrides = {}

    configs = {}
    errors = []

    # Set up a logger to capture errors
    logger = logging.getLogger('config_loader')
    logger.setLevel(logging.ERROR)

    # Create a handler that captures log records
    class ListHandler(logging.Handler):
        def __init__(self):
            super().__init__()
            self.records = []

        def emit(self, record):
            self.records.append(record)

    handler = ListHandler()
    logger.addHandler(handler)

    for filename in config_filenames:
        if not isinstance(filename, str):
            record = logging.LogRecord(
                name=logger.name,
                level=logging.ERROR,
                pathname='config_loader',
                lineno=0,
                msg=f"Invalid filename type: {type(filename)}",
                args=(),
                exc_info=None
            )
            errors.append(record)
            continue

        try:
            # Check if file exists
            if not os.path.exists(filename):
                record = logging.LogRecord(
                    name=logger.name,
                    level=logging.ERROR,
                    pathname='config_loader',
                    lineno=0,
                    msg=f"Configuration file not found: {filename}",
                    args=(),
                    exc_info=None
                )
                errors.append(record)
                continue

            # Determine file type by extension
            ext = os.path.splitext(filename)[1].lower()

            if ext == '.json':
                with open(filename, 'r', encoding='utf-8') as f:
                    config = json.load(f)
            elif ext in ['.yaml', '.yml']:
                with open(filename, 'r', encoding='utf-8') as f:
                    config = yaml.safe_load(f)
            else:
                # Try JSON first, then YAML
                try:
                    with open(filename, 'r', encoding='utf-8') as f:
                        content = f.read()
                    config = json.loads(content)
                except json.JSONDecodeError:
                    with open(filename, 'r', encoding='utf-8') as f:
                        config = yaml.safe_load(f)

            # Validate that config is a dict
            if not isinstance(config, dict):
                record = logging.LogRecord(
                    name=logger.name,
                    level=logging.ERROR,
                    pathname='config_loader',
                    lineno=0,
                    msg=f"Configuration file {filename} did not parse to a dictionary",
                    args=(),
                    exc_info=None
                )
                errors.append(record)
                continue

            # Apply overrides
            if overrides:
                config = _deep_merge(config, overrides)

            # Resolve environment variables if requested
            if resolve_env:
                config = _resolve_env_vars(config)

            configs[filename] = config

        except Exception as e:
            record = logging.LogRecord(
                name=logger.name,
                level=logging.ERROR,
                pathname='config_loader',
                lineno=0,
                msg=f"Error loading configuration file {filename}: {str(e)}",
                args=(),
                exc_info=None
            )
            errors.append(record)

    # Remove the handler
    logger.removeHandler(handler)

    return configs, errors

def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        if protocol_version is not None:
            if not isinstance(protocol_version, tuple):
                raise TypeError("protocol_version must be a tuple")
            # Check if the version is supported
            if protocol_version in cls._protocol_handlers:
                return {protocol_version: cls._protocol_handlers[protocol_version]}
            else:
                return {}
        else:
            return dict(cls._protocol_handlers)

def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        """
        if values is None:
            raise ValueError("values cannot be None")
        if not hasattr(values, '__iter__'):
            raise TypeError("values must be an iterable")

        bookmarks = []
        for value in values:
            if not isinstance(value, str):
                raise TypeError("Each value must be a string")
            if not all(ord(c) < 128 for c in value):
                raise ValueError("Each value must be an ASCII string")
            bookmarks.append(value)

        return cls(bookmarks)

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not isinstance(iface, type):
        raise TypeError("iface must be a class")
    if not isinstance(candidate, type):
        raise TypeError("candidate must be a class")

    # Check if candidate is a subclass of iface or is iface itself
    if not issubclass(candidate, iface):
        if tentative:
            return False
        else:
            raise TypeError(f"{candidate} does not provide {iface}")

    # If tentative, just return True if it's a subclass
    if tentative:
        return True

    # For non-tentative, we might want to check if all abstract methods are implemented
    # This is a simplified check; a full implementation would inspect abstract methods
    try:
        # Try to instantiate to see if it's abstract (this is a heuristic)
        # But we don't want to actually instantiate, so we check for abstract methods
        import inspect
        abstract_methods = []
        for name, method in inspect.getmembers(iface):
            if inspect.isfunction(method) and getattr(method, '__isabstractmethod__', False):
                abstract_methods.append(name)

        for method_name in abstract_methods:
            if not hasattr(candidate, method_name):
                raise TypeError(f"{candidate} does not implement abstract method {method_name} of {iface}")
            # Check if the method is actually implemented (not abstract)
            method = getattr(candidate, method_name)
            if inspect.isfunction(method) and getattr(method, '__isabstractmethod__', False):
                raise TypeError(f"{candidate} does not implement abstract method {method_name} of {iface}")
    except Exception as e:
        if not tentative:
            raise TypeError(f"{candidate} does not correctly provide {iface}: {e}")
        else:
            return False

    return True

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if key in self:
        value = self[key]
        del self[key]
        return value
    elif default is not __marker:
        return default
    else:
        raise KeyError(key)

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    if not self:
        raise KeyError("popitem(): dictionary is empty")
    key = random.choice(list(self.keys()))
    value = self[key]
    del self[key]
    return (key, value)

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    try:
        # Check if it's a public message
        if hasattr(request, 'public_message') and request.public_message:
            return 'public_message'

        # Check if it's a private message
        if hasattr(request, 'private_message') and request.private_message:
            return 'private_message'

        # Check if it's a legacy payload
        if hasattr(request, 'legacy_payload') and request.legacy_payload:
            return 'legacy_payload'

        # If none of the above, return None or a default value
        return None
    except Exception as e:
        # Handle any unexpected errors
        return None

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        # Check if the request has a path that starts with /_matrix
        if hasattr(request, 'path') and request.path:
            if request.path.startswith('/_matrix'):
                return True

        # Check if the request has a header indicating Matrix
        if hasattr(request, 'headers') and request.headers:
            if 'X-Matrix-Request' in request.headers:
                return True

        # Check if the request has a specific attribute
        if hasattr(request, 'is_matrix_request') and request.is_matrix_request:
            return True

    except Exception:
        pass

    return False

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    """
    if dt is None:
        raise ValueError("dt cannot be None")
    try:
        # D* nodes expect format: YYYY-MM-DD HH:MM:SS
        return dt.strftime("%Y-%m-%d %H:%M:%S")
    except (AttributeError, TypeError) as e:
        raise ValueError(f"Invalid datetime object: {e}")

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str):
        return False
    if not tag:
        return False
    # A valid tag should contain only alphanumeric characters and underscores
    # and should not start with a digit
    if not tag[0].isalpha() and tag[0] != '_':
        return False
    for char in tag:
        if not (char.isalnum() or char == '_'):
            return False
    return True

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    result = {}
    for child in node:
        tag = child.tag
        if tag in result:
            # If the tag already exists, convert to list
            if not isinstance(result[tag], list):
                result[tag] = [result[tag]]
            result[tag].append(child)
        else:
            result[tag] = child
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Validate input
    if not url or not isinstance(url, str):
        raise ValueError("url must be a non-empty string")

    # Ensure url ends with a slash for proper path concatenation
    if not url.endswith('/'):
        url = url + '/'

    # Default document path
    if document_path is None:
        document_path = '.well-known/nodeinfo'
    else:
        # Ensure document_path doesn't start with a slash
        if document_path.startswith('/'):
            document_path = document_path[1:]

    # Construct the full document URL
    document_url = url + document_path

    # Return the NodeInfo document structure
    return {
        "links": {
            "self": document_url,
            "http://nodeinfo.diaspora.software/ns/schema/2.0": document_url + "?rel=http://nodeinfo.diaspora.software/ns/schema/2.0",
            "http://nodeinfo.diaspora.software/ns/schema/1.0": document_url + "?rel=http://nodeinfo.diaspora.software/ns/schema/1.0"
        },
        "version": "2.0"
    }

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json

    from typing import Dict

    from xml.etree import ElementTree
    # Try JSON first
    try:
        data = json.loads(document)
        if isinstance(data, dict):
            return data
    except (json.JSONDecodeError, ValueError):
        pass

    # Try XRD (XML)
    try:
        root = ElementTree.fromstring(document)
        result = {}

        # XRD structure: <XRD xmlns="http://docs.oasis-open.org/webfinger/xrd">
        # We need to handle namespaces
        ns = {'xrd': 'http://docs.oasis-open.org/webfinger/xrd'}

        # Get subject
        subject_elem = root.find('xrd:subject', ns)
        if subject_elem is not None:
            result['subject'] = subject_elem.text

        # Get aliases
        aliases = []
        for alias_elem in root.findall('xrd:alias', ns):
            if alias_elem.text:
                aliases.append(alias_elem.text)
        if aliases:
            result['aliases'] = aliases

        # Get links
        links = []
        for link_elem in root.findall('xrd:link', ns):
            link = {}
            for attr in link_elem.attrib:
                # Remove namespace from attribute name if present
                if ':' in attr:
                    attr_name = attr.split(':')[-1]
                else:
                    attr_name = attr
                link[attr_name] = link_elem.attrib[attr]
            links.append(link)
        if links:
            result['links'] = links

        return result
    except ElementTree.ParseError:
        pass

    # If neither JSON nor XRD, return empty dict or raise
    return {}

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    import requests
    from xml.etree import ElementTree
    import re

    # Validate host
    if not host or not isinstance(host, str):
        raise ValueError("Host must be a non-empty string")

    # Remove protocol if present
    host = host.strip()
    if host.startswith('http://'):
        host = host[7:]
    elif host.startswith('https://'):
        host = host[8:]

    # Remove trailing slash
    host = host.rstrip('/')

    # Construct the host-meta URL
    url = f"https://{host}/.well-known/host-meta"

    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
    except requests.exceptions.RequestException as e:
        raise ConnectionError(f"Failed to retrieve host-meta from {host}: {e}")

    # Parse the XML response
    try:
        root = ElementTree.fromstring(response.content)
    except ElementTree.ParseError as e:
        raise ValueError(f"Invalid XML in host-meta response: {e}")

    # Create a simple XRD-like object
    class XRD:
        def __init__(self, root):
            self.root = root
            self.links = []
            self.parse()

        def parse(self):
            # Handle both XRD and XRDS namespaces
            ns = {'xrd': 'http://docs.oasis-open.org/ns/xri/xrd-1.0'}
            for link in self.root.findall('.//xrd:Link', ns):
                self.links.append({
                    'rel': link.get('rel'),
                    'href': link.get('href'),
                    'type': link.get('type')
                })

    return XRD(root)

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    import requests
    import urllib3

    try:
        # Determine the method
        method = method.lower()

        # Prepare the request
        if method == "post":
            response = requests.post(url, data=data, timeout=timeout, *args, **kwargs)
        elif method == "get":
            response = requests.get(url, data=data, timeout=timeout, *args, **kwargs)
        elif method == "put":
            response = requests.put(url, data=data, timeout=timeout, *args, **kwargs)
        elif method == "delete":
            response = requests.delete(url, data=data, timeout=timeout, *args, **kwargs)
        elif method == "patch":
            response = requests.patch(url, data=data, timeout=timeout, *args, **kwargs)
        elif method == "head":
            response = requests.head(url, data=data, timeout=timeout, *args, **kwargs)
        elif method == "options":
            response = requests.options(url, data=data, timeout=timeout, *args, **kwargs)
        else:
            # Use the generic request method
            response = requests.request(method, url, data=data, timeout=timeout, *args, **kwargs)

        return (response.status_code, None)
    except requests.exceptions.RequestException as e:
        return (None, e)
    except Exception as e:
        return (None, e)

def list_of_file_names(settings_dirs, spec_option):
