    if not hasattr(self, 'requires_args'):
        return True
    for arg in self.requires_args:
        if arg not in args:
            return False
    return True

def _get_conditionally_required_args(self, command_name, options_spec,
                                     args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required_args = []
    for option in options_spec:
        if not isinstance(option, dict):
            continue
        required_when = option.get('required_when')
        if required_when is None:
            continue
        # Check if the condition is met
        # The condition is a list of (arg_name, expected_value) tuples
        # or a list of arg_names (meaning the arg must be present)
        condition_met = True
        if isinstance(required_when, list):
            for condition in required_when:
                if isinstance(condition, (list, tuple)) and len(condition) == 2:
                    arg_name, expected_value = condition
                    # Check if the argument is in args and matches expected value
                    if arg_name not in args:
                        condition_met = False
                        break
                    if args[arg_name] != expected_value:
                        condition_met = False
                        break
                elif isinstance(condition, str):
                    # Just check if the argument is present
                    if condition not in args:
                        condition_met = False
                        break
                else:
                    # Unknown condition format, skip
                    condition_met = False
                    break
        elif isinstance(required_when, str):
            # Single condition as a string
            if required_when not in args:
                condition_met = False
        else:
            # Unknown condition format
            condition_met = False

        if condition_met:
            arg_name = option.get('name')
            if arg_name:
                required_args.append(arg_name)

    return required_args

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Assuming self has a 'length' attribute that specifies the maximum allowed length
    # and args is a dictionary or object with attributes that need to be checked.
    # We'll assume args is a dictionary where keys are argument names and values are the actual values.
    # We'll check if any string value exceeds the specified length.

    if not hasattr(self, 'length'):
        raise AttributeError("Object does not have a 'length' attribute")

    max_length = self.length

    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary")

    for key, value in args.items():
        if isinstance(value, str):
            if len(value) > max_length:
                raise ValueError(f"Argument '{key}' value length {len(value)} exceeds maximum allowed length {max_length}")
        elif isinstance(value, (list, tuple)):
            if len(value) > max_length:
                raise ValueError(f"Argument '{key}' value length {len(value)} exceeds maximum allowed length {max_length}")
        # For other types, we might not check length, or we could convert to string and check
        # But typically, length validation is for strings and sequences

def validate_choices_args(self, args):
        """Check if value of choice arguments is one of the available choices.

        :param args: The received arguments.
        """
        for arg in args:
            if arg.choices is not None:
                if arg.value not in arg.choices:
                    raise ValueError(f"Invalid value '{arg.value}' for argument '{arg.name}'. Must be one of {arg.choices}")

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Assuming self has attributes min_value and max_value
    # and args is a dictionary or object with attributes
    # We need to check each argument value against min and max

    # If args is a dictionary
    if isinstance(args, dict):
        for key, value in args.items():
            if not isinstance(value, (int, float)):
                continue
            if value < self.min_value or value > self.max_value:
                raise ValueError(f"Argument '{key}' value {value} is out of range [{self.min_value}, {self.max_value}]")
    # If args is an object with attributes
    elif hasattr(args, '__dict__'):
        for key, value in vars(args).items():
            if not isinstance(value, (int, float)):
                continue
            if value < self.min_value or value > self.max_value:
                raise ValueError(f"Argument '{key}' value {value} is out of range [{self.min_value}, {self.max_value}]")
    # If args is a list or tuple
    elif isinstance(args, (list, tuple)):
        for i, value in enumerate(args):
            if not isinstance(value, (int, float)):
                continue
            if value < self.min_value or value > self.max_value:
                raise ValueError(f"Argument at index {i} value {value} is out of range [{self.min_value}, {self.max_value}]")
    # If args is a single value
    else:
        if isinstance(args, (int, float)):
            if args < self.min_value or args > self.max_value:
                raise ValueError(f"Argument value {args} is out of range [{self.min_value}, {self.max_value}]")

