    }

    for arg in args:
        if isinstance(arg, dict):
            for key, value in arg.items():
                if key in control_arg_names:
                    control_args[key] = value
                else:
                    nested_args[key] = value
        elif isinstance(arg, str):
            # If it's a string, it might be a key-value pair or just a key
            if '=' in arg:
                key, value = arg.split('=', 1)
                key = key.strip()
                value = value.strip()
                if key in control_arg_names:
                    control_args[key] = value
                else:
                    nested_args[key] = value
            else:
                # Just a key, assume boolean True
                if arg in control_arg_names:
                    control_args[arg] = True
                else:
                    nested_args[arg] = True
        else:
            # For other types, we can't determine the key, so skip or handle appropriately
            pass

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is None:
        return vars_dict

    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")

    if not isinstance(extra_vars, (list, tuple)):
        raise TypeError("extra_vars must be a list or tuple")

    for item in extra_vars:
        if isinstance(item, str):
            if '=' in item:
                key, value = item.split('=', 1)
                vars_dict[key] = value
            else:
                # If no '=' found, treat the whole string as key with empty value
                vars_dict[item] = ""
        elif isinstance(item, dict):
            vars_dict.update(item)
        else:
            raise TypeError(f"Unsupported item type in extra_vars: {type(item)}")

    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import subprocess
    import shlex
    import os
    import json

    # Build the command
    cmd = ['ansible-playbook']

    # Add verbosity
    if verbose is not None:
        if isinstance(verbose, int):
            if verbose > 0:
                cmd.append('-' + 'v' * verbose)
        elif isinstance(verbose, str):
            cmd.append('-' + verbose)

    # Add extra vars
    if extra_vars is not None:
        if isinstance(extra_vars, dict):
            # Convert dict to JSON string for --extra-vars
            extra_vars_str = json.dumps(extra_vars)
            cmd.extend(['--extra-vars', extra_vars_str])
        elif isinstance(extra_vars, str):
            cmd.extend(['--extra-vars', extra_vars])

    # Add ansible_args
    if ansible_args is not None:
        if isinstance(ansible_args, dict):
            for key, value in ansible_args.items():
                if value is None:
                    # Boolean flag
                    cmd.append(key)
                else:
                    cmd.append(key)
                    if isinstance(value, bool):
                        if value:
                            cmd.append('true')
                        else:
                            cmd.append('false')
                    elif isinstance(value, (list, tuple)):
                        for v in value:
                            cmd.append(str(v))
                    else:
                        cmd.append(str(value))
        elif isinstance(ansible_args, list):
            cmd.extend(ansible_args)

    # Add playbook path
    cmd.append(playbook_path)

    # Set up environment
    env = os.environ.copy()

    # If ir_workspace has an environment or config, we might need to set some env vars
    # For now, we'll just use the current environment
    # If ir_workspace has a method to get environment, we could use it
    # But since we don't know the exact API, we'll keep it simple

    # Execute the command
    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            env=env,
            check=False
        )

        # Return the result
        return {
            'returncode': result.returncode,
            'stdout': result.stdout,
            'stderr': result.stderr
        }
    except Exception as e:
        return {
            'returncode': -1,
            'stdout': '',
            'stderr': str(e)
        }

def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    """Runs ansible cli with vars dict

    :param vars_dict: dict, Will be passed as Ansible extra-vars
    :param cli_args: the list  of command line arguments
    :param ir_workspace: An Infrared Workspace object represents the active
     workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :return: ansible results
    """
    import subprocess
    import json
    import os
    import tempfile

    # Build the command
    cmd = ['ansible-playbook']

    # Add extra vars if provided
    if vars_dict:
        # Convert vars_dict to JSON string for extra-vars
        extra_vars = json.dumps(vars_dict)
        cmd.extend(['-e', extra_vars])

    # Add the cli_args
    cmd.extend(cli_args)

    # Set up environment
    env = os.environ.copy()

    # If ir_workspace is provided, set the workspace directory
    if ir_workspace:
        try:
            workspace_dir = ir_workspace.get_workspace_dir()
            if workspace_dir:
                env['ANSIBLE_WORKSPACE'] = workspace_dir
        except Exception:
            pass

    # If ir_plugin is provided, set plugin-related environment variables
    if ir_plugin:
        try:
            plugin_name = ir_plugin.get_name()
            if plugin_name:
                env['ANSIBLE_PLUGIN'] = plugin_name
        except Exception:
            pass

    # Run the command
    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            env=env,
            timeout=3600  # 1 hour timeout
        )

        # Parse the output
        stdout = result.stdout
        stderr = result.stderr
        return_code = result.returncode

        # Try to parse JSON output if available
        ansible_results = {}
        if stdout:
            try:
                # Ansible might output JSON at the end
                lines = stdout.strip().split('\n')
                for line in reversed(lines):
                    line = line.strip()
                    if line.startswith('{'):
                        try:
                            ansible_results = json.loads(line)
                            break
                        except json.JSONDecodeError:
                            continue
            except Exception:
                pass

        # If no JSON found, create a basic result structure
        if not ansible_results:
            ansible_results = {
                'stdout': stdout,
                'stderr': stderr,
                'return_code': return_code
            }

        # Add return code to results
        ansible_results['return_code'] = return_code

        return ansible_results

    except subprocess.TimeoutExpired:
        return {
            'error': 'Command timed out',
            'return_code': -1
        }
    except Exception as e:
        return {
            'error': str(e),
            'return_code': -1
        }

def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of with arguments
       """
        if not isinstance(values_dict, dict):
            raise TypeError("values_dict must be a dictionary")

        # Define a mapping of argument names to their expected types
        # This is a simplified example; in a real scenario, this would be
        # more comprehensive and possibly data-driven
        type_mapping = {
            'port': int,
            'timeout': int,
            'retries': int,
            'verbose': bool,
            'debug': bool,
            'dry_run': bool,
            'count': int,
            'size': int,
            'limit': int,
            'offset': int,
            'threshold': float,
            'ratio': float,
            'probability': float,
        }

        # Convert values based on the type mapping
        for key, value in values_dict.items():
            if key in type_mapping:
                target_type = type_mapping[key]
                try:
                    if target_type is bool:
                        # Handle boolean conversion
                        if isinstance(value, str):
                            value_lower = value.lower()
                            if value_lower in ('true', '1', 'yes', 'on'):
                                values_dict[key] = True
                            elif value_lower in ('false', '0', 'no', 'off'):
                                values_dict[key] = False
                            else:
                                # If it's not a recognizable boolean string, keep as is or raise
                                values_dict[key] = bool(value)
                        else:
                            values_dict[key] = bool(value)
                    else:
                        values_dict[key] = target_type(value)
                except (ValueError, TypeError):
                    # If conversion fails, leave the value as is or handle appropriately
                    # For robustness, we might want to log this or raise a specific error
                    pass

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    import yaml

    # Define the path to the plugin spec file
    spec_file = os.path.join(plugin_dir, 'plugin_spec.json')
    spec_file_yaml = os.path.join(plugin_dir, 'plugin_spec.yaml')
    spec_file_yml = os.path.join(plugin_dir, 'plugin_spec.yml')

    # Try to load the spec from JSON first
    if os.path.exists(spec_file):
        try:
            with open(spec_file, 'r') as f:
                spec = json.load(f)
        except (json.JSONDecodeError, IOError) as e:
            raise ValueError(f"Failed to load plugin spec from JSON: {e}")
    elif os.path.exists(spec_file_yaml):
        try:
            with open(spec_file_yaml, 'r') as f:
                spec = yaml.safe_load(f)
        except (yaml.YAMLError, IOError) as e:
            raise ValueError(f"Failed to load plugin spec from YAML: {e}")
    elif os.path.exists(spec_file_yml):
        try:
            with open(spec_file_yml, 'r') as f:
                spec = yaml.safe_load(f)
        except (yaml.YAMLError, IOError) as e:
            raise ValueError(f"Failed to load plugin spec from YAML: {e}")
    else:
        raise FileNotFoundError(f"Plugin spec file not found in {plugin_dir}")

    # Flatten the dictionary
    def flatten_dict(d, parent_key='', sep='.'):
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten_dict(v, new_key, sep=sep).items())
            elif isinstance(v, list):
                # For lists, we can either keep them as is or flatten them
                # Here we keep them as is, but if needed, we can flatten lists too
                items.append((new_key, v))
            else:
                items.append((new_key, v))
        return dict(items)

    return flatten_dict(spec)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    import os
    if 'CONFIG_PATH' not in os.environ:
        # Set a default config path if not already defined
        os.environ['CONFIG_PATH'] = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'config.json')
